def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = CASH_ADVANCE_FEE_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Get cash advance fee parameters from vault fetcher.

    Args:
        vault (SmartContractVault): Vault object
        param_fetcher_id (str, optional): Cash advance fetcher id. Defaults to
            CASH_ADVANCE_FEE_POF_ID.

    Returns:
        dict[str, datetime | Decimal | str | None]: _description_
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def calculate_cash_advance_fee(
    amount: Decimal,
    percentage: Decimal,
    flat_amount: Decimal,
) -> Decimal:
    """Calculates cash advance fee as max(amount * percentage, flat_amount).

    Args:
        amount: The cash advance transaction amount.
        percentage: Fee percentage (e.g. 0.03 for 3%).
        flat_amount: Flat minimum fee (e.g. 3).

    Returns:
        The fee amount.
    """
    percentage_fee = (amount * percentage).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return max(percentage_fee, flat_amount)


def charge_cash_advance_fee(
    state: state_utils.SmartContractState,
    transaction_amount: Decimal,
    account_type: str = "",
    fetchers_config: CashAdvanceFeeFetchersConfig = DEFAULT_CASH_ADVANCE_FEE_FETCHERS_CONFIG,
) -> list[CustomInstruction]:
    """Charges a cash advance fee on a cash advance transaction (post_posting_hook).

    The fee is max(amount * percentage, flat_amount). Debits the customer's FEES
    address and credits the internal income account.

    Args:
        state: The current state of the smart contract.
        transaction_amount: The cash advance amount.
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for the fee.
    """
    state = state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, fetchers_config.param_fetcher_id),
    )

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            CASH_ADVANCE_FEE_PERCENTAGE_PARAM.id,
            CASH_ADVANCE_FEE_FLAT_AMOUNT_PARAM.id,
            CASH_ADVANCE_FEE_INCOME_ACCOUNT_PARAM.id,
        },
    )
    assert rejection is None, rejection

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    percentage: Decimal = state.parameters[CASH_ADVANCE_FEE_PERCENTAGE_PARAM.id]  # type: ignore
    flat_amount: Decimal = state.parameters[CASH_ADVANCE_FEE_FLAT_AMOUNT_PARAM.id]  # type: ignore
    income_account: str = state.parameters[CASH_ADVANCE_FEE_INCOME_ACCOUNT_PARAM.id]  # type: ignore

    fee = calculate_cash_advance_fee(transaction_amount, percentage, flat_amount)

    if fee <= 0:
        return []

    return [
        CustomInstruction(
            postings=posting_utils.create_postings(
                amount=fee,
                debit_account=state.vault.account_id,
                debit_address=apex_addresses.FEES,
                credit_account=income_account,
                denomination=denomination,
            ),
            value_datetime=state.effective_datetime,
            instruction_details=posting_utils.standard_instruction_details(
                description=f"Cash advance fee: {fee} on transaction of {transaction_amount}",
                event_type=CASH_ADVANCE_FEE_EVENT,
                gl_impacted=True,
                account_type=account_type,
            ),
            override_all_restrictions=True,
        )
    ]
